return ['domain'=>'zinn-connector','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'hr','project-id-version'=>'zinn-connector','pot-creation-date'=>'2026-09-11T18:44:12+00:00','po-revision-date'=>'2026-09-11T18:44:12+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Connector'=>'Zinn® Connector','https://zinndigital.com/wordpress-plugins/zinn-connector'=>'https://zinndigital.com/wordpress-plugins/zinn-connector','Connects this WordPress site to Zinn Digital® so scheduled articles can be published to it. Paste a pairing code from your Zinn® dashboard and the plugin sets up its own credential — nothing is copied by hand.'=>'Povezuje ovu WordPress stranicu sa Zinn Digital® kako bi se na nju mogle objavljivati zakazane objave. Zalijepite kod za uparivanje s vaše Zinn® nadzorne ploče i dodatak sam postavlja svoje vjerodajnice — ništa se ne kopira ručno.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Stored. Type a new value to replace it.'=>'Pohranjeno. Unesite novu vrijednost da biste je zamijenili.','Filter this list…'=>'Filtriraj ovaj popis…','Filter this list'=>'Filtriraj ovaj popis','Nothing matches that filter.'=>'Ništa ne odgovara tom filteru.','Add a row'=>'Dodaj redak','Remove this row'=>'Ukloni ovaj red','Remove'=>'Ukloni','Zinn Digital®'=>'Zinn Digital®','Zinn Digital® — overview'=>'Zinn Digital® — pregled','Overview'=>'Pregled','Every Zinn® plugin on this site, and whether it is working.'=>'Svaki Zinn® dodatak na ovoj stranici i radi li on.','No connection is needed for this plugin.'=>'Za ovaj dodatak nije potrebna nikakva veza.','Open settings'=>'Otvorite postavke','You do not have permission to change these settings.'=>'Nemate dozvolu za promjenu ovih postavki.','Settings sections'=>'Sekcije postavki','Support'=>'Podrška','Save changes'=>'Spremi promjene','Tools'=>'Alati','Export settings'=>'Izvoz postavki','Reset to defaults'=>'Vrati na zadano','This puts every setting on this plugin back to its default. Continue?'=>'Ovo vraća svaku postavku ovog dodatka na zadane vrijednosti. Nastaviti?','Diagnostics for support'=>'Dijagnostika za podršku','Import a settings file'=>'Uvoz datoteke s postavkama','Import'=>'Uvoz','Exported files never contain passwords, tokens or API keys — you will need to enter those again on the new site.'=>'Izvezene datoteke nikada ne sadrže lozinke, tokena ili API ključeve – morat ćete ih ponovno unijeti na novoj web-lokaciji.','Settings saved.'=>'Postavke su spremljene.','Every setting on this plugin is back to its default.'=>'Sve postavke na ovom dodatku vraćene su na zadane vrijednosti.','Done.'=>'Gotovo.','That action is not available.'=>'Ta radnja nije dostupna.','That file could not be read. Choose a settings file exported from a Zinn® plugin.'=>'Datoteku nije moguće pročitati. Odaberite datoteku postavki izvezenu iz Zinn® dodatka.','That file is too large to be a settings export.'=>'Ta je datoteka prevelika da bi bila izvoz postavki.','That file is not a Zinn® settings export.'=>'Ta datoteka nije izvoz Zinn® postavki.','That file was exported from a different plugin (%s), so importing it here would store settings this plugin does not understand.'=>'Ta je datoteka izvezena iz drugog dodatka (%s), pa bi njen uvoz ovdje pohranio postavke koje ovaj dodatak ne prepoznaje.','%d setting imported. Passwords and API keys are never in an export, so enter those again.'=>'Uvezen je %d postavk%. Lozinke i ključevi API-ja nikada se ne nalaze u izvozu, stoga ih unesite ponovno.' . "\0" . 'Uvezeno je %d postavki. Zaporke i API ključevi nikada nisu uključeni u izvoz, stoga ih ponovno unesite.' . "\0" . 'Uvezeno je %d postavki. Zaporke i API ključevi nikada nisu uključeni u izvoz, stoga ih ponovno unesite.','The archive would be %1$d MB, over the %2$d MB limit set on this site. Raise the limit, or exclude some folders, on the Zinn Digital® → Connector → Backups screen.'=>'Arhiva bi iznosila %1$d MB, što premašuje ograničenje od %2$d MB postavljeno na ovoj web-lokaciji. Povećajte ograničenje ili izuzmite neke mape na zaslonu Zinn Digital® → Connector → Backups.','This site\'s PHP cannot create archives, so a backup could not be made.'=>'PHP ove stranice ne može stสร้างiti arhive, pa sigurnosna kopija nije mogla biti izrađena.','Could not create a temporary file.'=>'Nije moguće stvoriti privremenu datoteku.','This site\'s files could not be archived.'=>'Datoteke ove web-lokacije nije bilo moguće arhivirati.','This site\'s PHP cannot compress archives, so a backup could not be made.'=>'PHP ove stranice ne može komprimirati arhive, pa nije bilo moguće napraviti sigurnosnu kopiju.','A backup of this site needs about %1$s of temporary space and only %2$s is free, so it was not attempted.'=>'Izrada sigurnosne kopije ove web-lokacije zahtijeva oko %1$s privremenog prostora, a slobodno je samo %2$s, stoga nije ni pokušana.','This WordPress user cannot publish posts, so a connection made now could not publish either. Sign in as a user who can, and try again.'=>'Ovaj WordPress korisnik ne može objavljivati postove, tako da se ni veza ostvarena sada ne bi mogla objaviti. Prijavite se kao korisnik koji to može i pokušajte ponovno.','Application passwords are turned off on this site, so we cannot create a credential. Ask your host to enable them, or connect the site with a password you create yourself in your Zinn Digital® dashboard.'=>'Lozinke za aplikacije su isključene na ovoj stranici, stoga ne možemo izraditi vjerodajnicu. Zatražite od svog pružatelja usluge da ih omogući ili povežite stranicu pomoću lozinke koju sami kreirate na svojoj upravljačkoj ploči Zinn Digital®.','WordPress would not create a credential for this site. Nothing has been sent anywhere.'=>'WordPress nije mogao izraditi vjerodajnicu za ovo web-mjesto. Ništa nije poslano nigdje.','We could not reach Zinn Digital® from this site. Nothing was connected, and the credential we made has been removed. Check the site can make outgoing requests, and try again.'=>'Nismo mogli uspostaviti vezu s platformom Zinn Digital® s ove stranice. Ništa nije bilo povezano, a izrađeni vjerodajnički podaci su uklonjeni. Provjerite može li stranica slati odlazne zahtjeve i pokušajte ponovno.','Zinn Digital® could not finish connecting this site. The problem is on our side, not with your pairing code — nothing was connected, and the credential we made has been removed. The same pairing code still works: try again in a few minutes.'=>'Zinn Digital® nije mogao dovršiti povezivanje ove web-lokacije. Problem je na našoj strani, a ne s vašim kodom za uparivanje – ništa nije povezano, a stvoreni vjerodajni podaci su uklonjeni. Isti kod za uparivanje i dalje radi: pokušajte ponovno za nekoliko minuta.','Zinn Digital® did not accept that pairing code. Nothing was connected. Generate a fresh code in your dashboard and try again.'=>'Zinn Digital® nije prihvatio taj kôd za uparivanje. Ništa nije povezano. Generirajte novi kôd na svojoj upravljačkoj ploči i pokušajte ponovno.','Connected. Zinn Digital® can now publish to this site.'=>'Povezano. Zinn Digital® sada može objavljivati na ovoj stranici.','Connected'=>'Povezano','Connecting…'=>'Povezivanje…','Connected, but something needs attention'=>'Povezano, ali nešto zahtijeva pažnju','Not connected'=>'Nije povezano','Running on your own account'=>'Radi na vašem računu','We could not check this'=>'Nismo mogli provjeriti ovo','This plugin did not say why. Send a diagnostics report and we will look.'=>'Ovaj dodatak nije naveo razlog. Pošaljite dijagnostičko izvješće i mi ćemo ga pregledati.','Connection status'=>'Status veze','Last checked %s ago.'=>'Zadnji put provjereno prije %s.','(opens in a new tab)'=>'(otvara se u novoj kartici)','Send this to Zinn® support'=>'Pošaljite ovo Zinn® podršci','This is exactly what will be sent — nothing else, and nothing hidden. Your passwords, tokens and API keys are not in it.'=>'Upravo ovo će biti poslano — ništa drugo i ništa skriveno. Vaše lozinke, tokeni i API ključevi nisu uključeni u to.','The diagnostics report that will be sent'=>'Dijagnostičko izvješće koje će biti poslano','Copy to clipboard'=>'Kopiraj u međuspremnik','Send this report to Zinn® support'=>'Pošaljite ovo izvješće Zinn® podršci','We open a support ticket for you and reply by email. If you would rather not send it, copy it above and paste it into a ticket yourself.'=>'Otvorit ćemo vam zahtjev za podršku i odgovoriti putem e-pošte. Ako ga radije ne biste poslali, kopirajte ga iznad i sami ga zalijepite u zahtjev.','Copied'=>'Kopirano','We could not reach Zinn Digital® from this server (%s). Copy the report above and open a ticket instead — nothing about your settings is wrong.'=>'Nismo mogli dosegnuti Zinn Digital® s ovog poslužitelja (%s). Kopirajte gore navedeno izvješće i umjesto toga otvorite zahtjev — s vašim postavkama nije ništa u redu.','Sent. Zinn® support has your report and will reply by email.'=>'Podrška za Zinn® primila je vaše izvješće i odgovorit će vam putem e-pošte.','Sent. Zinn® support has your report — reference %s — and will reply by email.'=>'Podrška za Zinn® primila je vaše izvješće — referenca %s — i odgovorit će vam putem e-pošte.','You have sent several reports in a short time. Wait a few minutes and try again — the earlier ones did arrive.'=>'Poslali ste nekoliko izvješća u kratkom vremenu. Pričekajte nekoliko minuta i pokušajte ponovno – ona prethodna su stigla.','Zinn Digital® could not accept the report just now — that is our end, not yours. Try again shortly, or copy the report above into a ticket.'=>'Zinn Digital® trenutno nije mogao prihvatiti izvješće — problem je s naše strane, ne s vaše. Pokušajte ponovno uskoro ili kopirajte gornje izvješće u tiket.','The report was refused (HTTP %d). Copy it above and open a ticket, quoting that number.'=>'Izvještaj je odbijen (HTTP %d). Kopirajte ga gore i otvorite zahtjev navodeći taj broj.','This site’s owner has turned off image uploads for Zinn Digital® in the Zinn® Connector settings.'=>'Vlasnik ove web-lokacije isključio je prijenos slika za Zinn Digital® u postavkama za Zinn® Connector.','This site’s owner has turned off edits to existing articles for Zinn Digital® in the Zinn® Connector settings.'=>'Vlasnik ove web-lokacije onemogućio je uređivanje postojećih članaka za Zinn Digital® u postavkama za Zinn® Connector.','New article on your site: %s'=>'Novi članak na vašoj stranici: %s','Zinn Digital® has added an article to your site.

Title: %1$s
Edit it: %2$s
Status: %3$s

Turn these emails off on the Zinn Digital® → Connector → Publishing screen.'=>'Zinn Digital® je dodao članak na vašu web-lokaciju.

Naslov: %1$s
Uredite ga: %2$s
Status: %3$s

Isključite ove e-poruke na zaslonu Zinn Digital® → Connector → Publishing.','%s — guides and services'=>'%s — vodiči i usluge','User guides'=>'Korisnički vodiči','Read the %s user guide'=>'Pročitajte korisnički priručnik za %s','Hide this'=>'Sakrij ovo','Zinn® hosting for WordPress'=>'Zinn® hosting za WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, dnevne sigurnosne kopije, besplatna migracija i upravljačka ploča prilagođena osobama koje upravljaju s više web-mjesta.','The Zinn® marketplace'=>'Zinn® tržnica','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Kupujte i prodajite postojeće internetske stranice, domene i postavljanja poveznica, uz sigurno čuvanje novca sve dok obje strane ne budu zadovoljne.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — zaposlite ljude koji se time bave za život','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Naše globalno tržište slobodnih zanimanja: pregledajte više od 10.000 gotovih usluga pisaca, dizajnera, programera i SEO stručnjaka ili objavite projekt i dopustite im da daju ponude.','Connector'=>'Konektor','Connection'=>'Veza','Publishing'=>'Objavljivanje','Backups'=>'Sigurnosne kopije','Advanced'=>'Napredno','Check the connection now'=>'Provjeri vezu sada','Disconnect this site'=>'Odspoji ovo web-mjesto','This revokes the credential Zinn Digital® uses, so we can no longer publish to this site. Anything already published stays. Continue?'=>'Ovo poništava vjerodajnicu koju Zinn Digital® koristi, tako da je više ne možemo objavljivati na ovoj web-lokaciji. Sve što je već objavljeno ostaje. Nastaviti?','What we may do on this site'=>'Što možemo učiniti na ovoj web-lokaciji','The credential we hold is an ordinary WordPress application password, so WordPress itself decides what is possible. These narrow it further, on your side.'=>'Vjerodajnica koju posjedujemo obična je WordPress aplikacijska lozinka, tako da sam WordPress odlučuje što je moguće. Ove opcije to dodatno sužavaju, s vaše strane.','Publish articles as'=>'Objavi članke kao','Choose “a draft” if you would rather read everything before it goes live.'=>'Odaberite „skica” ako radije želite sve pročitati prije nego što postane javno dostupno.','Published straight away'=>'Odmah objavljeno','A draft, for me to review'=>'Nacrt za moj pregled','Pending review'=>'Na čekanju','Scheduled, using the date we send'=>'Planirano, prema datumu koji šaljemo','Show the author as'=>'Prikaži autora kao','Which of your users appears as the author. This does not change who we sign in as.'=>'Koji se vaš korisnik prikazuje kao autor. Ovo ne mijenja s čijom se prijavom prijavljujemo.','Put articles in'=>'Objavi članke u','Allow images'=>'Dozvoli slike','Let Zinn Digital® upload images into this site’s media library'=>'Dopustite tvrtki Zinn Digital® učitavanje slika u biblioteku medija ove web-lokacije','Turn this off and articles arrive without their images. Nothing already uploaded is removed.'=>'Isključite ovo i članci stižu bez svojih slika. Ništa što je već učitano nije uklonjeno.','Allow edits'=>'Dopusti uređivanje','Let Zinn Digital® update an article it published before'=>'Neka Zinn Digital® ažurira članak koji je prethodno objavio','Used for corrections and re-optimisation. It never touches anything you wrote yourself.'=>'Koristi se za ispravke i ponovnu optimizaciju. Nikada ne dira ništa što ste sami napisali.','Tell me when something is published'=>'Obavijesti me kada je nešto objavljeno','Leave blank for no email. One message per article, from your own site.'=>'Ostavite prazno ako ne želite e-poštu. Jedna poruka po članku, s vaše vlastite stranice.','Off-site backups'=>'Izvanmrežne sigurnosne kopije','This site sends its own backup straight to Zinn® storage. Nothing passes through our servers on the way.'=>'Ova stranica šalje vlastitu sigurnosnu kopiju izravno u Zinn® pohranu. Ništa ne prolazi kroz naše poslužitelje usput.','Back this site up to Zinn Digital®'=>'Napravite sigurnosnu kopiju ove web-lokacije na platformi Zinn Digital®','Backup token'=>'Sigurnosni token za izradu kopije','Set for you when the site was connected. You will only need to touch this if support asks.'=>'Postavljeno kada je web-mjesto povezano. Ovo ćete morati mijenjati samo ako podrška zatraži.','Leave these out'=>'Izostavi ovo','One path per line, relative to wp-content — for example <code>cache</code> or <code>uploads/backups</code>. Caches and other backup plugins’ folders are the usual candidates.'=>'Jedna staza po retku, relativno u odnosu na wp-content — na primjer <code>cache</code> ili <code>uploads/backups</code>. Predmemorije i mape drugih dodataka za sigurnosne kopije uobičajeni su kandidati.','Stop if the archive would exceed'=>'Zaustavi ako arhiva premašuje','Megabytes. A shared host will usually kill a very large archive part-way; a bound turns that into a message instead of a silent failure.'=>'Megabajti. Dijeljeni poslužitelj obično će prekinuti vrlo veliku arhivu na pola puta; ograničenje to pretvara u poruku umjesto u tihi neuspjeh.','Detailed logging'=>'Detaljno zapisivanje dnevnika','Record what this plugin does, for support'=>'Zabilježite što ovaj dodatak radi, radi podrške','Kept on this site, capped at the last 50 entries, and included in a diagnostics report. Turn it on before reproducing a problem.'=>'Pohranjeno na ovoj web-lokaciji, ograničeno na zadnjih 50 unosa i uključeno u izvješće o dijagnostici. Uključite to prije nego što reproducirate problem.','On uninstall'=>'Pri deinstalaciji','Delete this plugin’s settings when it is uninstalled'=>'Izbriši postavke ovog dodatka prilikom deinstalacije','Uninstalling never revokes the application password — that is deliberate, so uninstalling to try something else does not break your publishing. Use Disconnect above if you want the credential gone.'=>'Deinstaliranje nikada ne opoziva lozinku aplikacije – to je namjerno napravljeno kako deinstaliranje radi isprobavanja nečeg drugog ne bi prekinulo vaše objavljivanje. Upotrijebite gornju opciju Prekini vezu ako želite ukloniti vjerodajnicu.','The user we sign in as'=>'Korisnik s čijim se računom prijavljujemo','The site’s default category'=>'Zadana kategorija web-mjesta','Connect this site again'=>'Ponovno poveži ovu stranicu','Connect this site'=>'Povežite ovu web-lokaciju','Open your Zinn Digital® dashboard, go to Content → Other sites, and press “Get a pairing code”. Paste it below.'=>'Otvorite svoju nadzornu ploču Zinn Digital®, idite na Sadržaj → Ostale web-lokacije i pritisnite „Zatražite kod za uparivanje”. Zalijepite ga u nastavku.','Connecting again creates a fresh credential and leaves the old one in place — use Disconnect first if you want the old one gone.'=>'Ponovno povezivanje stvara novu vjerodajnicu, a staru ostavlja na mjestu — upotrijebite prvo Prekini vezu ako želite da stara nestane.','Pairing code'=>'Kod za uparivanje','It expires thirty minutes after you generate it, and can only be used once.'=>'Istječe trideset minuta nakon što ga generirate i može se iskoristiti samo jednom.','You are not allowed to connect this site.'=>'Nije vam dopušteno povezivanje ove stranice.','This site is not connected to Zinn Digital®.'=>'Ova stranica nije povezana s tvrtkom Zinn Digital®.','Nothing is wrong — it has simply not been paired yet. Get a pairing code from your Zinn® dashboard and paste it into this plugin’s settings.'=>'Ništa nije u kvaru — jednostavno još nije upareno. Nabavite kod za uparivanje sa svoje Zinn® upravljačke ploče i zalijepite ga u postavke ovog dodatka.','Open my Zinn® dashboard'=>'Otvorite moju Zinn® upravljačku ploču','The connection is broken.'=>'Veza je prekinuta.','The WordPress user the credential belonged to (%s) no longer exists on this site, so nothing we send can be published. Connect again as a user who can publish.'=>'WordPress korisnik kojem su pripadali ovi pristupni podaci (%s) više ne postoji na ovoj stranici, tako da se ništa što pošaljemo ne može objaviti. Povežite se ponovno kao korisnik koji može objavljivati.','The “Zinn Digital® (publishing)” application password has been deleted from this site, so we can no longer sign in. Connect again to create a new one — nothing else was lost.'=>'Lozinka aplikacije “Zinn Digital® (publishing)” izbrisana je s ove stranice, tako da se više ne možemo prijaviti. Povežite se ponovno kako biste izradili novu – ništa drugo nije izgubljeno.','See this site’s application passwords'=>'Pogledajte aplikacijske lozinke ove web-lokacije','Connected, but publishing would fail.'=>'Povezano, ali objavljivanje ne bi uspjelo.','The credential belongs to %s, and that user can no longer publish posts. Sign-in still works, so nothing looks wrong until an article is due. Give that user the ability to publish, or connect again as somebody who can.'=>'Podaci za prijavu pripadaju korisniku %s, a taj korisnik više ne može objavljivati članke. Prijava i dalje radi, stoga sve izgleda u redu sve dok ne dođe vrijeme za objavu članka. Omogućite tom korisniku objavljivanje ili se ponovno prijavite kao netko tko to može.','Edit that user'=>'Uredi tog korisnika','Connected here — we could not reach Zinn Digital® to confirm.'=>'Ovdje povezani — nismo mogli kontaktirati Zinn Digital® radi potvrde.','Connected, but your Zinn® account needs attention.'=>'Povezani ste, ali vašem Zinn® računu je potrebna pažnja.','Connected to Zinn Digital®.'=>'Spojeno na Zinn Digital®.','Connected to Zinn Digital® as %s.'=>'Povezani ste sa Zinn Digital® kao %s.','Publishing as'=>'Objavljivanje kao','Zinn® site ID'=>'Zinn® ID web-lokacije','This server could not reach api.zinndigital.com (%s). That is usually a firewall or an outbound-connection rule on your host, not a problem with your Zinn® account — publishing may still be working.'=>'Ovaj poslužitelj nije mogao dosegnuti api.zinndigital.com (%s). To je obično vatrozid ili pravilo odlazne veze na vašem poslužitelju, a ne problem s vašim Zinn® računom — objavljivanje možda još uvijek radi.','Zinn Digital® answered with an error of its own — that is our end, not yours. Publishing is unaffected while this clears.'=>'Zinn Digital® je vratio vlastitu pogrešku – to je naš problem, a ne vaš. Objavljivanje nije ugroženo dok se ovo ne riješi.','Your Zinn® account is not currently able to publish to this site. Your dashboard says why.'=>'Vaš Zinn® račun trenutno ne može objavljivati na ovoj web-lokaciji. Vaša upravljačka ploča navodi zašto.','Zinn Digital® answered HTTP %d, which we do not recognise. Send a diagnostics report from the Support tab and we will look — do not change anything here first.'=>'Zinn Digital® je vratio HTTP %d kod koji ne prepoznajemo. Pošaljite izvješće o dijagnostici s kartice Podrška i mi ćemo provjeriti — nemojte ništa mijenjati ovdje prije toga.','Check again now'=>'Provjeri ponovno sada','Checked. The connection is live.'=>'Provjereno. Veza je uspostavljena.','We could not remove the application password, so this site is still connected. Delete “Zinn Digital® (publishing)” on your profile screen and try again — we have changed nothing.'=>'Nismo mogli ukloniti zaporku aplikacije, pa je ova web-lokacija još uvijek povezana. Izbrišite “Zinn Digital® (publishing)” na zaslonu profila i pokušajte ponovno — ništa nismo promijenili.','Disconnected. The application password has been revoked, so Zinn Digital® can no longer publish to this site. Nothing already published was touched.'=>'Prekinuta veza. Lozinka aplikacije je opozvana, tako da Zinn Digital® više ne može objavljivati na ovoj web-lokaciji. Ništa što je već objavljeno nije dirano.','That file could not be read from this server, so nothing was uploaded.'=>'Ta se datoteka nije mogla pročitati s ovog poslužitelja, pa ništa nije učitano.','This site could not stream the upload, so nothing was sent.'=>'Ova stranica nije mogla prenositi prijenos, pa ništa nije poslanu.','This file is %1$s and this site\'s PHP has no cURL, so the largest it can upload is %2$s.'=>'Ova datoteka ima %1$s, a PHP ove stranice nema cURL, tako da je najveća veličina koju može prenijeti %2$s.','The upload could not be completed.'=>'Prijenos nije mogao biti dovršen.','Storage refused the upload (HTTP %d).'=>'Pohrana je odbila prijenos (HTTP %d).','Style preset'=>'Prezadana tema','A starting point. Anything below overrides it.'=>'Polazna točka. Sve ispod toga ima prednost.','Use my own colours and sizes'=>'Upotrijebi moje vlastite boje i veličine','Leave this off and the preset is used exactly as it is.'=>'Ostavite ovo isključeno i predložak će se koristiti točno onakav kakav jest.','See the Zinn Digital® release notes.'=>'Pogledajte bilješke o izdanju Zinn Digital®.','The downloaded update failed its integrity check and was not installed.'=>'Preuzeto ažuriranje nije prošlo provjeru integriteta i nije instalirano.']];